		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379} – учитель магов: сначала прочитайте предмет {item:282416}",
		["{npc:251389}, in the watchtower"] = "{npc:251389} – в сторожевой башне",
