t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "Приключения: исследуйте карту мира",
		["Adventure: {npc:16042}"] = "Приключения: {npc:16042}",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Классы дают 27 очков: каждый класс на уровнях 25, 45 и 60. Каждый класс засчитывается один раз на учетную запись, так что второй персонаж уже прокачанного класса ничего не добавит, а новый класс – добавит. Первый персонаж, достигший 25-го уровня, обычно и открывает Систему наследия.",
		["Classes: level 25"] = "Классы: уровень 25",
		["Classes: level 45"] = "Классы: уровень 45",
		["Classes: level 60"] = "Классы: уровень 60",
		["Dire Maul East"] = "Забытый Город: восток",
		["Dire Maul North"] = "Забытый Город: север",
		["Dire Maul West"] = "Забытый Город: запад",
		["Dungeons: level 15-25"] = "Подземелья: уровни 15-25",
		["Dungeons: level 26-45"] = "Подземелья: уровни 26-45",
		["Dungeons: level 46-60"] = "Подземелья: уровни 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Каждая профессия производства дает 3 очка: на 150, 225 и 300. Ранги засчитываются один раз на профессию для всей учетной записи. Следуйте гайду Polestar «{skill:171} 1-300» (Профессии). Профессия производства на 150 также открывает Систему наследия.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:164} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:165} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:197} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:202} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:333} 1-300» (Профессии).",
		["Legacy Challenges"] = "Испытания наследия",
		["Level 45 with this character's class."] = "45-й уровень этим классом персонажа.",
		["Level 60 with this character's class."] = "60-й уровень этим классом персонажа.",
		["PvP: Field of Honor"] = "PvP: Field of Honor",
		["PvP: battleground reputations (Alliance)"] = "PvP: репутация полей боя (Альянс)",
		["PvP: battleground reputations (Horde)"] = "PvP: репутация полей боя (Орда)",
		["PvP: honor ranks"] = "PvP: звания чести",
		["Raids: Barrow Deeps"] = "Рейды: Barrow Deeps",
		["Raids: Hyjal Summit"] = "Рейды: Вершина Хиджала",
		["Raids: {npc:10184}"] = "Рейды: {npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "Звания 3, 7, 10, 13 и 14 дают по очку. Polestar пока не видит ваше высшее звание, так что отмечайте их сами. Правила чести Forever для получения званий подробно не опубликованы; в Classic звание зависит от еженедельного места по чести, а для 13-14 нужно много недель на вершине.",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "В PvP-сезоне Field of Honor есть еженедельные задания; выполнение заданий 4-й, 7-й и 10-й недель дает по очку. Эти задания – новые в Forever, их нет в наших данных, так что отмечайте их сами.",
		["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "Этот шаг пока не может сам проверить всю карту; он станет отслеживаемой целью, когда будут записаны ID достижений наследия.",
		["Tradeskills: {skill:164}"] = "Профессии: {skill:164}",
